export const DIVISION_TYPES = [
    'tab',
    'dropdown',
    'anchor',
    'language',
    'product',
    'version',
    'item',
];
export const CONTENT_TYPES = ['page', 'group'];
export const FILESYSTEM_TYPES = ['file', 'file_directory'];
export const ROOT_NODE = 'root';
export const PAGE_ROLES = ['viewer', 'editor', 'manager'];
export const pageRoleRank = (role) => PAGE_ROLES.indexOf(role);
export const isAtLeastPageRole = (role, minimum) => role != null && pageRoleRank(role) >= pageRoleRank(minimum);
export const WILDCARD_MINT_USER = '*';
export const isWildcardMintUser = (mintUser) => mintUser === WILDCARD_MINT_USER;
export const PRIVATE_NAVIGATION_NODE_TYPES = ['private_folder', 'private_page'];
